# -*- coding: utf-8 -*-
"""主持人专用规则库：总结归纳、全局掌控、批判思维、引导讨论等。

每条规则包含：
- id: 规则编号，例如 "MR001"（Moderator Rule）
- category: 类型（总结、引导、批判、决策、沟通）
- text: 规则的自然语言表述
- guidance: 面向主持人的操作建议
"""
from typing import List, Dict


MODERATOR_RULES: List[Dict[str, str]] = [
  # ========== 总结归纳 (MR001-MR020) ==========
  {"id": "MR001", "category": "总结", "text": "有效的总结应当提炼核心观点，而非简单罗列所有发言内容。", "guidance": "主持人应识别每位专家发言中的关键主张，用一两句话概括。"},
  {"id": "MR002", "category": "总结", "text": "总结时应区分事实陈述与价值判断，避免混淆。", "guidance": "明确标注哪些是客观数据，哪些是专家的主观建议。"},
  {"id": "MR003", "category": "总结", "text": "好的总结能让未参与讨论的人快速理解会议要点。", "guidance": "总结应具有独立可读性，避免过多指代和省略。"},
  {"id": "MR004", "category": "总结", "text": "总结应保持中立，不偏向任何一方观点。", "guidance": "避免在总结中使用带有倾向性的形容词。"},
  {"id": "MR005", "category": "总结", "text": "分层总结比线性总结更有效：先全局后细节。", "guidance": "先给出一句话核心结论，再展开具体分论点。"},
  {"id": "MR006", "category": "总结", "text": "总结中应明确指出专家之间的共识点。", "guidance": "用'各方一致认为...'等表述标明共识。"},
  {"id": "MR007", "category": "总结", "text": "总结中应如实反映专家之间的分歧。", "guidance": "用'在...问题上，A专家认为...而B专家认为...'呈现分歧。"},
  {"id": "MR008", "category": "总结", "text": "避免在总结中添加专家未表达的观点。", "guidance": "主持人可以提问澄清，但不能替专家发言。"},
  {"id": "MR009", "category": "总结", "text": "总结应关注可操作的建议，而非抽象的原则。", "guidance": "将'应该重视安全'转化为'建议每日检查冷链温度'。"},
  {"id": "MR010", "category": "总结", "text": "定期进行阶段性总结有助于保持讨论聚焦。", "guidance": "每轮讨论结束时做一次小结，防止话题漂移。"},

  # ========== 全局掌控 (MR011-MR030) ==========
  {"id": "MR011", "category": "全局", "text": "主持人应对讨论议题有全面的背景了解。", "guidance": "会前准备相关资料，了解事件来龙去脉。"},
  {"id": "MR012", "category": "全局", "text": "把握讨论节奏，避免在次要问题上过度停留。", "guidance": "设定每个议题的大致时间，适时推进。"},
  {"id": "MR013", "category": "全局", "text": "关注沉默的专家，确保每个人都有发言机会。", "guidance": "主动邀请未发言的专家分享观点。"},
  {"id": "MR014", "category": "全局", "text": "识别讨论中的关键转折点，及时引导深入。", "guidance": "当出现重要分歧或新视角时，追问细节。"},
  {"id": "MR015", "category": "全局", "text": "将专家发言与公众关切进行关联。", "guidance": "定期提醒专家考虑建议的社会接受度。"},
  {"id": "MR016", "category": "全局", "text": "平衡技术讨论与决策导向的比重。", "guidance": "避免陷入纯技术争论而忘记决策目标。"},
  {"id": "MR017", "category": "全局", "text": "识别讨论中的逻辑漏洞或信息缺口。", "guidance": "发现不完整的论证时，请专家补充依据。"},
  {"id": "MR018", "category": "全局", "text": "将多轮讨论的成果进行递进式整合。", "guidance": "后一轮讨论应建立在前一轮共识的基础上。"},
  {"id": "MR019", "category": "全局", "text": "预判可能的争议点，提前准备引导策略。", "guidance": "对敏感话题准备中立的引导问题。"},
  {"id": "MR020", "category": "全局", "text": "始终牢记会议的最终目标：形成可执行的决策。", "guidance": "将讨论引向具体的行动建议。"},

  # ========== 引导讨论 (MR021-MR040) ==========
  {"id": "MR021", "category": "引导", "text": "用开放性问题激发深入思考，用封闭性问题确认共识。", "guidance": "'您认为原因是什么？'vs'大家是否同意这一点？'"},
  {"id": "MR022", "category": "引导", "text": "当讨论偏离主题时，温和但坚定地拉回焦点。", "guidance": "'这个观点很有价值，我们可以稍后讨论，现在先聚焦...'"},
  {"id": "MR023", "category": "引导", "text": "将抽象讨论引向具体情境。", "guidance": "'能否举一个具体的例子来说明？'"},
  {"id": "MR024", "category": "引导", "text": "鼓励专家之间的直接对话和回应。", "guidance": "'B专家，您如何看待A专家刚才的观点？'"},
  {"id": "MR025", "category": "引导", "text": "引导专家考虑不同利益相关方的视角。", "guidance": "'从家长的角度来看，这个建议可能会...'"},
  {"id": "MR026", "category": "引导", "text": "将复杂问题拆解为若干子问题逐一讨论。", "guidance": "先讨论'是什么'，再讨论'为什么'，最后讨论'怎么办'。"},
  {"id": "MR027", "category": "引导", "text": "用'如果...那么...'引导专家思考后果。", "guidance": "'如果采取这个措施，可能会带来什么影响？'"},
  {"id": "MR028", "category": "引导", "text": "适时提供信息补充，但不主导专家判断。", "guidance": "提供背景数据时保持中立陈述。"},
  {"id": "MR029", "category": "引导", "text": "当专家陷入僵局时，尝试重新框定问题。", "guidance": "'如果我们换一个角度来看这个问题...'"},
  {"id": "MR030", "category": "引导", "text": "引导专家从短期应急和长期制度两个层面思考。", "guidance": "'除了眼前的紧急措施，长远来看应该...'"},

  # ========== 批判思维 (MR031-MR050) ==========
  {"id": "MR031", "category": "批判", "text": "对过于绝对的结论保持警惕。", "guidance": "当专家说'一定'或'绝对'时，追问是否有例外。"},
  {"id": "MR032", "category": "批判", "text": "区分相关性与因果性。", "guidance": "'两者相关'不等于'A导致B'，需要更多证据。"},
  {"id": "MR033", "category": "批判", "text": "识别论证中的假设前提。", "guidance": "'这个结论成立的前提是什么？'"},
  {"id": "MR034", "category": "批判", "text": "警惕确认偏误：只关注支持自己观点的证据。", "guidance": "主动询问是否有反面证据或案例。"},
  {"id": "MR035", "category": "批判", "text": "避免诉诸权威：专家身份不等于观点正确。", "guidance": "关注论证质量而非发言者身份。"},
  {"id": "MR036", "category": "批判", "text": "识别滑坡谬误：A不必然导致极端后果Z。", "guidance": "要求提供中间环节的证据。"},
  {"id": "MR037", "category": "批判", "text": "警惕过度概括：个案不能代表普遍情况。", "guidance": "'这个案例是否具有代表性？'"},
  {"id": "MR038", "category": "批判", "text": "区分应然与实然：'应该如何'vs'实际如何'。", "guidance": "理想方案需要考虑现实可行性。"},
  {"id": "MR039", "category": "批判", "text": "对数据来源和统计方法保持审慎。", "guidance": "'这个数据的样本量和来源是什么？'"},
  {"id": "MR040", "category": "批判", "text": "识别虚假两难：不是只有A和B两个选项。", "guidance": "'除了这两个方案，是否还有其他可能？'"},

  # ========== 决策制定 (MR041-MR060) ==========
  {"id": "MR041", "category": "决策", "text": "决策应基于充分讨论后的共识，而非主持人的个人判断。", "guidance": "决策前确认各方是否认可。"},
  {"id": "MR042", "category": "决策", "text": "明确决策的优先级：紧急性vs重要性。", "guidance": "区分'立即要做'和'重要但可以稍后'。"},
  {"id": "MR043", "category": "决策", "text": "每项决策都应指定责任主体。", "guidance": "'谁来负责执行这项措施？'"},
  {"id": "MR044", "category": "决策", "text": "决策应包含可衡量的成功标准。", "guidance": "'如何判断这项措施是否有效？'"},
  {"id": "MR045", "category": "决策", "text": "考虑决策的潜在负面影响和应对预案。", "guidance": "'如果效果不佳，备选方案是什么？'"},
  {"id": "MR046", "category": "决策", "text": "平衡多方利益，寻求帕累托改进。", "guidance": "尽量找到让所有相关方都能接受的方案。"},
  {"id": "MR047", "category": "决策", "text": "决策表述应清晰具体，避免模糊语言。", "guidance": "将'加强管理'转化为'每日三次巡查并记录'。"},
  {"id": "MR048", "category": "决策", "text": "保留对决策的复盘和调整机制。", "guidance": "'一周后我们复盘执行效果并调整'。"},
  {"id": "MR049", "category": "决策", "text": "决策应考虑资源约束和可行性。", "guidance": "'实施这项措施需要多少人力和预算？'"},
  {"id": "MR050", "category": "决策", "text": "在不确定性较高时，采用渐进式决策。", "guidance": "先小范围试点，再逐步推广。"},

  # ========== 沟通技巧 (MR051-MR060) ==========
  {"id": "MR051", "category": "沟通", "text": "使用中立、非评判性的语言。", "guidance": "避免'您这个观点有问题'，改用'能否再详细解释一下'。"},
  {"id": "MR052", "category": "沟通", "text": "肯定专家的贡献，营造积极的讨论氛围。", "guidance": "'感谢您的专业见解，这对我们很有帮助'。"},
  {"id": "MR053", "category": "沟通", "text": "用复述确认理解，减少误解。", "guidance": "'如果我理解正确的话，您的意思是...'"},
  {"id": "MR054", "category": "沟通", "text": "面对情绪化发言，先共情后引导。", "guidance": "'我理解您的担忧，让我们一起看看如何解决...'"},
  {"id": "MR055", "category": "沟通", "text": "将技术术语转化为通俗表达。", "guidance": "确保非专业人士也能理解讨论内容。"},
  {"id": "MR056", "category": "沟通", "text": "适时使用沉默，给专家思考空间。", "guidance": "提问后不要急于填补沉默。"},
  {"id": "MR057", "category": "沟通", "text": "对敏感话题采用间接提问。", "guidance": "'有人认为...您怎么看？'"},
  {"id": "MR058", "category": "沟通", "text": "用'我们'而非'你们'营造协作感。", "guidance": "'我们如何解决这个问题'比'你们应该...'更好。"},
  {"id": "MR059", "category": "沟通", "text": "明确表达感谢和认可。", "guidance": "会议结束时感谢每位专家的参与。"},
  {"id": "MR060", "category": "沟通", "text": "保持专业但不失温度的表达。", "guidance": "理性分析的同时，对受影响群体表达关切。"},

  # ========== 一、平台主持基础能力与信息归纳核心知识 (MR061-MR090) ==========
  {"id": "MR061", "category": "基础能力", "text": "掌握信息分层归纳方法，能将复杂议题拆解为【核心矛盾-关键数据-关联主体-潜在影响】四层结构，为专家聚焦讨论提供清晰框架。", "guidance": "来源：《主持人媒介素养与信息处理指南》"},
  {"id": "MR062", "category": "基础能力", "text": "熟悉跨领域信息整合技巧，针对多专家参与场景，可通过【议题共性+领域特性】分类法，提炼不同领域专家的共同关注点与差异化视角。", "guidance": "来源：《跨学科议题主持策略》"},
  {"id": "MR063", "category": "基础能力", "text": "具备数据可视化转化能力，能将教育经费投入、食品抽检合格率、市场价格波动等数据转化为【趋势图表+关键结论】形式。", "guidance": "来源：《数据驱动型主持实践手册》"},
  {"id": "MR064", "category": "基础能力", "text": "掌握信息真实性核验方法，对嘉宾提及的政策文件、案例数据，可即时对照权威来源，引导专家基于真实信息展开讨论。", "guidance": "来源：《媒介信息核查规范与实践》"},
  {"id": "MR065", "category": "基础能力", "text": "熟悉信息优先级排序逻辑，在多议题并行场景中，能依据【社会影响度-公众关注度-政策时效性】原则确定讨论顺序。", "guidance": "来源：《公共议题主持议程设置指南》"},
  {"id": "MR066", "category": "基础能力", "text": "具备模糊信息澄清能力，当专家表述存在歧义或信息不全时，可通过【定义确认-范围界定-补充提问】三步法引导专家明确观点。", "guidance": "来源：《主持人沟通技巧与议题引导》"},
  {"id": "MR067", "category": "基础能力", "text": "掌握多维度信息对比框架，针对同一议题可从【教育管理责任-食品标准执行-市场监管措施】三个维度归纳信息。", "guidance": "来源：《跨领域议题对比分析模型》"},
  {"id": "MR068", "category": "基础能力", "text": "熟悉信息留白设计技巧，在归纳信息时保留【争议点-数据缺口-政策盲区】，引导专家主动补充观点，激发批判性讨论。", "guidance": "来源：《互动型主持信息设计策略》"},
  {"id": "MR069", "category": "基础能力", "text": "具备动态信息更新能力，在直播或研讨过程中能实时整合新发布的政策文件、突发案例，引导专家即时分析。", "guidance": "来源：《实时性议题主持应对手册》"},
  {"id": "MR070", "category": "基础能力", "text": "掌握受众视角转化能力，可将专家讨论的专业信息转化为【公众关切点+生活关联度】表述，反向引导专家针对性解答。", "guidance": "来源：《主持人受众同理心培养与实践》"},
  {"id": "MR071", "category": "基础能力", "text": "熟悉信息逻辑链构建方法，针对复杂议题能梳理【政策出台背景-执行难点-专家分歧-改进建议】逻辑链。", "guidance": "来源：《公共政策议题主持逻辑构建指南》"},
  {"id": "MR072", "category": "基础能力", "text": "具备冗余信息过滤能力，在专家发言中精准识别【重复观点-无关数据-主观臆断】，通过【总结提炼+聚焦提问】引导讨论回归核心。", "guidance": "来源：《高效主持信息筛选与优化策略》"},
  {"id": "MR073", "category": "基础能力", "text": "掌握跨领域术语转化技巧，能将教育领域的【核心素养】、食品领域的【HACCP体系】、市场监管领域的【垄断协议】等专业术语转化为通用表述。", "guidance": "来源：《跨领域沟通术语转化手册》"},
  {"id": "MR074", "category": "基础能力", "text": "熟悉信息关联性挖掘方法，针对单一案例能挖掘其与【教育监管漏洞-食品生产标准-市场监管执法】的关联。", "guidance": "来源：《案例型议题关联分析主持策略》"},
  {"id": "MR075", "category": "基础能力", "text": "具备信息风险预警能力，在归纳信息时识别【数据过时-政策误读-案例极端化】风险，及时向专家提示。", "guidance": "来源：《主持信息风险防控规范》"},
  {"id": "MR076", "category": "基础能力", "text": "掌握观点冲突归纳技巧，当专家存在分歧时可归纳【分歧焦点-支撑依据-潜在后果】，引导双方围绕焦点展开理性辩论。", "guidance": "来源：《观点冲突型议题主持应对指南》"},
  {"id": "MR077", "category": "基础能力", "text": "熟悉信息结构化呈现方式，采用【总-分-总】结构，先归纳议题核心结论，再分领域呈现专家观点，最后总结共识与待解问题。", "guidance": "来源：《结构化主持信息呈现模板》"},
  {"id": "MR078", "category": "基础能力", "text": "具备隐性信息捕捉能力，能从专家发言的【语气变化-数据回避-观点模糊】中捕捉隐性态度，促使专家明确立场。", "guidance": "来源：《主持人隐性信息识别与引导技巧》"},
  {"id": "MR079", "category": "基础能力", "text": "掌握跨场次信息衔接方法，在系列研讨中能归纳前一场次的【核心观点-未决问题-数据缺口】，为后续讨论提供衔接点。", "guidance": "来源：《系列性议题主持信息衔接策略》"},
  {"id": "MR080", "category": "基础能力", "text": "熟悉信息权威性标注规则，在归纳专家观点时同步标注【观点依据-适用范围-局限性】，引导专家基于权威依据讨论。", "guidance": "来源：《权威信息标注与主持规范》"},
  {"id": "MR081", "category": "基础能力", "text": "具备复杂议题简化能力，可将复杂议题拆解为多个子议题，引导专家分模块讨论。", "guidance": "来源：《复杂议题简化与主持实践》"},
  {"id": "MR082", "category": "基础能力", "text": "掌握信息反馈验证技巧，归纳专家观点后通过【复述确认-补充追问-案例验证】三步法确保信息归纳准确。", "guidance": "来源：《主持信息反馈与验证机制》"},
  {"id": "MR083", "category": "基础能力", "text": "熟悉多平台信息整合逻辑，针对不同平台调整信息归纳颗粒度，适配专家表达与受众接收习惯。", "guidance": "来源：《多平台主持信息适配策略》"},
  {"id": "MR084", "category": "基础能力", "text": "具备政策信息解读框架，归纳政策时采用【政策目标-执行主体-考核指标-公众权益】框架引导专家评估政策落地效果。", "guidance": "来源：《公共政策解读主持框架指南》"},
  {"id": "MR085", "category": "基础能力", "text": "掌握案例信息深度挖掘方法，针对具体案例能挖掘【案例细节-违规点-涉及法规-改进建议】。", "guidance": "来源：《案例挖掘型主持信息处理手册》"},
  {"id": "MR086", "category": "基础能力", "text": "熟悉信息平衡呈现原则，在归纳不同专家观点时确保各领域观点均得到平等呈现。", "guidance": "来源：《主持信息平衡与客观性规范》"},
  {"id": "MR087", "category": "基础能力", "text": "具备突发信息应对能力，当讨论中出现突发信息时能快速归纳【信息核心-影响范围-专家需解答的问题】。", "guidance": "来源：《突发信息主持应对与信息整合指南》"},
  {"id": "MR088", "category": "基础能力", "text": "掌握长期议题信息跟踪方法，建立【政策更新-数据变化-专家观点演进】跟踪表，每次讨论前归纳最新动态。", "guidance": "来源：《长期议题信息跟踪与主持策略》"},
  {"id": "MR089", "category": "基础能力", "text": "熟悉跨文化信息处理技巧，若涉及国际议题能归纳【中外差异-本土化适配-监管挑战】。", "guidance": "来源：《跨文化议题主持信息处理规范》"},
  {"id": "MR090", "category": "基础能力", "text": "具备信息价值判断能力，能区分【关键信息-辅助信息-冗余信息】，优先归纳对专家讨论有核心价值的内容。", "guidance": "来源：《主持信息价值判断与筛选指南》"},

  # ========== 二、引导教育专家聚焦核心议题的知识 (MR091-MR120) ==========
  {"id": "MR091", "category": "教育引导", "text": "掌握教育政策落地痛点归纳方法，针对【双减】【普职分流】等政策可归纳【学校执行难点-教师适配问题-家长认知偏差-区域差异】。", "guidance": "来源：《教育政策落地难点与专家引导策略》"},
  {"id": "MR092", "category": "教育引导", "text": "熟悉教育资源分配核心矛盾提炼技巧，能将【城乡教育差距】议题拆解为【师资流动障碍-经费投入不均-硬件配置差异-优质生源流失】。", "guidance": "来源：《教育资源均衡化主持议题设计指南》"},
  {"id": "MR093", "category": "教育引导", "text": "具备教育质量评价维度归纳能力，可从【学业成绩-综合素质-身心健康-社会适应力】四个维度梳理评价体系的优势与不足。", "guidance": "来源：《教育评价改革主持讨论框架》"},
  {"id": "MR094", "category": "教育引导", "text": "掌握教育数字化转型关键问题捕捉技巧，能归纳【技术应用与教学需求脱节-数据安全风险-教师数字素养不足-区域发展不均衡】。", "guidance": "来源：《教育数字化主持议题引导策略》"},
  {"id": "MR095", "category": "教育引导", "text": "熟悉校外培训监管讨论引导方法，可归纳【合规培训界定-预收费资金监管-隐形变异培训识别-家校协同替代方案】。", "guidance": "来源：《校外培训监管专家引导手册》"},
  {"id": "MR096", "category": "教育引导", "text": "具备职业教育发展焦点归纳能力，能梳理【产教融合痛点-社会认知偏见-课程与产业脱节-技能认证衔接】。", "guidance": "来源：《职业教育发展主持议题设计规范》"},
  {"id": "MR097", "category": "教育引导", "text": "掌握基础教育课程改革讨论框架，针对新课标实施可归纳【核心素养落地路径-教材内容适配-教师备课挑战-学生接受度差异】。", "guidance": "来源：《基础教育课程改革主持引导指南》"},
  {"id": "MR098", "category": "教育引导", "text": "熟悉教育公平争议点提炼技巧，对【学区房政策】【特殊教育资源配置】等议题能归纳【政策初衷与现实偏差-不同群体权益平衡-监管漏洞-替代方案】。", "guidance": "来源：《教育公平议题主持专家引导策略》"},
  {"id": "MR099", "category": "教育引导", "text": "具备教师队伍建设关键议题归纳能力，可从【师德师风考核-职称评聘公平性-待遇保障差距-专业发展支持】维度引导讨论。", "guidance": "来源：《教师队伍建设主持讨论框架》"},
  {"id": "MR100", "category": "教育引导", "text": "掌握学生心理健康教育讨论引导方法，能归纳【心理问题识别难点-家校社协同盲区-课程设置有效性-危机干预机制】。", "guidance": "来源：《学生心理健康教育专家引导手册》"},
  {"id": "MR101", "category": "教育引导", "text": "熟悉学前教育发展痛点归纳技巧，可梳理【财政投入不足-师资流动性大-保教质量差异-入托难区域分布】。", "guidance": "来源：《学前教育发展主持议题设计指南》"},
  {"id": "MR102", "category": "教育引导", "text": "具备高等教育质量提升焦点捕捉能力，能归纳【学科建设与产业需求脱节-科研评价功利化-人才培养模式单一-国际竞争力不足】。", "guidance": "来源：《高等教育质量提升主持引导策略》"},
  {"id": "MR103", "category": "教育引导", "text": "掌握教育应急管理讨论框架，可归纳【预案科学性-演练实效性-家校沟通效率-资源储备充足性】。", "guidance": "来源：《校园应急管理专家引导规范》"},
  {"id": "MR104", "category": "教育引导", "text": "熟悉教育国际化讨论引导方法，能归纳【中外合作办学质量监管-国际课程本土化适配-跨文化人才培养标准-留学安全风险】。", "guidance": "来源：《教育国际化主持议题设计手册》"},
  {"id": "MR105", "category": "教育引导", "text": "具备教育科研成果转化痛点归纳能力，可梳理【科研与教学脱节-成果落地资金不足-校企合作机制障碍-评价激励缺失】。", "guidance": "来源：《教育科研转化主持引导策略》"},
  {"id": "MR106", "category": "教育引导", "text": "掌握农村教育发展关键问题提炼技巧，能归纳【政策扶持力度-资源供给效率-社会力量参与-内生发展动力】。", "guidance": "来源：《农村教育发展主持专家引导指南》"},
  {"id": "MR107", "category": "教育引导", "text": "熟悉特殊教育保障讨论框架，可归纳【残疾学生入学障碍-师资专业度不足-课程适配性差-社会融合支持缺失】。", "guidance": "来源：《特殊教育发展主持议题设计规范》"},
  {"id": "MR108", "category": "教育引导", "text": "具备教育收费监管焦点归纳能力，能梳理【学校乱收费类型-监管技术手段不足-家长维权难度-区域监管差异】。", "guidance": "来源：《教育收费监管专家引导手册》"},
  {"id": "MR109", "category": "教育引导", "text": "掌握家校共育难点讨论引导方法，可归纳【责任划分标准-沟通渠道有效性-家长教育能力-学校引导方式】。", "guidance": "来源：《家校共育主持引导策略》"},
  {"id": "MR110", "category": "教育引导", "text": "熟悉教育信息化伦理讨论框架，能归纳【学生数据隐私保护-算法推荐教育内容偏见-数字鸿沟扩大风险-教师技术伦理素养】。", "guidance": "来源：《教育信息化伦理主持议题设计指南》"},
  {"id": "MR111", "category": "教育引导", "text": "具备义务教育阶段辍学防控焦点归纳能力，可梳理【辍学原因区域差异-劝返复学难点-长效帮扶机制-政策执行监督】。", "guidance": "来源：《义务教育辍学防控专家引导规范》"},
  {"id": "MR112", "category": "教育引导", "text": "掌握教育考试改革讨论引导方法，能归纳【评价公平性-学生选择焦虑-学校课程设置-社会认可度】。", "guidance": "来源：《教育考试改革主持议题设计手册》"},
  {"id": "MR113", "category": "教育引导", "text": "熟悉校园文化建设关键议题归纳技巧，可从【文化育人功能发挥-学生主体参与不足-特色文化同质化-家校社协同共建】维度讨论。", "guidance": "来源：《校园文化建设主持引导策略》"},
  {"id": "MR114", "category": "教育引导", "text": "具备教育扶贫长效机制讨论框架，能归纳【脱贫后教育资源衔接-防止返贫监测-特色教育产业帮扶-教育扶智与扶志结合】。", "guidance": "来源：《教育扶贫长效机制专家引导指南》"},
  {"id": "MR115", "category": "教育引导", "text": "掌握中小学劳动教育落地难点归纳能力，可梳理【课程内容实用性-师资专业度-场地资源-评价体系缺失】。", "guidance": "来源：《中小学劳动教育主持议题设计规范》"},
  {"id": "MR116", "category": "教育引导", "text": "熟悉教育领域突发事件舆情应对讨论引导方法，能归纳【舆情爆发诱因-官方回应时效-专家发声作用-家校沟通协同】。", "guidance": "来源：《教育舆情应对专家引导手册》"},
  {"id": "MR117", "category": "教育引导", "text": "具备教育集团化办学争议点提炼技巧，可归纳【资源共享效率-品牌稀释风险-师资流动障碍-区域辐射效果】。", "guidance": "来源：《教育集团化办学主持引导策略》"},
  {"id": "MR118", "category": "教育引导", "text": "掌握学前教育【小学化】治理讨论框架，能归纳【治理政策执行难点-家长认知误区-幼儿园生存压力-替代教育内容】。", "guidance": "来源：《学前教育小学化治理主持议题设计指南》"},
  {"id": "MR119", "category": "教育引导", "text": "熟悉高校毕业生就业质量讨论引导方法，可归纳【就业质量评价标准-专业设置与市场需求匹配-就业指导实效性-创新创业支持】。", "guidance": "来源：《高校就业质量专家引导规范》"},
  {"id": "MR120", "category": "教育引导", "text": "具备教育领域信用体系建设焦点归纳能力，能梳理【教师信用评价指标-学校信用监管-学生诚信教育-信用信息应用边界】。", "guidance": "来源：《教育信用体系主持议题设计手册》"},

  # ========== 三、引导食品专家聚焦核心议题的知识 (MR121-MR150) ==========
  {"id": "MR121", "category": "食品引导", "text": "掌握食品安全全链条风险点归纳方法，可从【种植养殖-生产加工-流通储存-餐饮消费】维度引导食品专家聚焦风险防控。", "guidance": "来源：《食品安全全链条风险防控主持引导指南》"},
  {"id": "MR122", "category": "食品引导", "text": "熟悉食品添加剂争议点提炼技巧，能归纳【合规使用与超范围使用界限-消费者认知误区-检测技术局限性-标签标识透明度】。", "guidance": "来源：《食品添加剂讨论主持专家引导策略》"},
  {"id": "MR123", "category": "食品引导", "text": "具备食品安全标准讨论框架构建能力，可梳理【国家标准与国际标准差异-标准更新滞后性-地方标准适用性-企业标准备案监管】。", "guidance": "来源：《食品安全标准体系主持议题设计规范》"},
  {"id": "MR124", "category": "食品引导", "text": "掌握食品污染物防控焦点归纳技巧，能归纳【污染源头识别-检测技术灵敏度-防控措施有效性-风险预警机制】。", "guidance": "来源：《食品污染物防控专家引导手册》"},
  {"id": "MR125", "category": "食品引导", "text": "熟悉特殊人群食品安全讨论引导方法，可归纳【配方安全性-营养适配性-标签信息准确性-特殊储存要求】。", "guidance": "来源：《特殊人群食品安全主持议题设计指南》"},
  {"id": "MR126", "category": "食品引导", "text": "具备食品新业态风险归纳能力，针对直播带货食品、社区团购食材等场景能梳理【资质审核漏洞-物流保鲜短板-虚假宣传乱象-售后维权困难】。", "guidance": "来源：《食品新业态安全监管主持引导策略》"},
  {"id": "MR127", "category": "食品引导", "text": "掌握食品溯源体系讨论框架，可从【溯源技术应用-数据真实性核验-跨环节信息打通-消费者查询便捷性】维度分析溯源体系实效。", "guidance": "来源：《食品溯源体系建设主持讨论手册》"},
  {"id": "MR128", "category": "食品引导", "text": "熟悉食品安全事件应急处置引导方法，能归纳【原因排查难点-舆情应对节奏-涉事主体责任-长效防范措施】。", "guidance": "来源：《食品安全突发事件主持应对规范》"},
  {"id": "MR129", "category": "食品引导", "text": "具备食品生产加工合规性讨论焦点提炼技巧，可梳理【生产流程标准化-洁净区管理-添加剂精准投放-出厂检验严格度】。", "guidance": "来源：《食品生产环节监管主持议题设计策略》"},
  {"id": "MR130", "category": "食品引导", "text": "掌握餐饮服务食品安全引导逻辑，能归纳【后厨明厨亮灶覆盖率-从业人员健康管理-餐具消毒流程-食材进货查验】。", "guidance": "来源：《餐饮服务安全主持讨论框架》"},
  {"id": "MR131", "category": "食品引导", "text": "熟悉进口食品监管讨论引导方法，可归纳【入境检验检疫流程-中文标签合规性-海外溯源信息对接-跨境电商监管盲区】。", "guidance": "来源：《进口食品安全主持引导手册》"},
  {"id": "MR132", "category": "食品引导", "text": "具备食品虚假宣传识别讨论框架构建能力，能梳理【宣传话术误导性-检测报告造假-有机绿色标识滥用-直播带货夸大宣传】。", "guidance": "来源：《食品虚假宣传治理主持议题设计指南》"},
  {"id": "MR133", "category": "食品引导", "text": "掌握食品保质期与储存条件讨论引导技巧，可归纳【保质期标注规范-储存条件影响-临期食品流通监管-变质风险预警】。", "guidance": "来源：《食品保质期管理主持讨论策略》"},
  {"id": "MR134", "category": "食品引导", "text": "熟悉食品行业诚信体系建设讨论焦点归纳能力，能梳理【企业信用评价指标-失信联合惩戒-诚信激励政策-消费者信任重建】。", "guidance": "来源：《食品行业诚信建设主持引导手册》"},
  {"id": "MR135", "category": "食品引导", "text": "具备食品检测技术发展讨论框架，可从【快速检测技术应用-实验室检测精度-现场检测设备便携性-检测成本控制】维度分析。", "guidance": "来源：《食品检测技术创新主持议题设计规范》"},
  {"id": "MR136", "category": "食品引导", "text": "掌握农产品质量安全讨论引导方法，能归纳【农药兽药规范使用-产地环境监测-病虫害绿色防控-采摘上市检验】。", "guidance": "来源：《农产品安全监管主持引导策略》"},
  {"id": "MR137", "category": "食品引导", "text": "熟悉食品包装安全讨论焦点提炼技巧，可梳理【包装材料安全性-包装标识规范性-保鲜包装技术风险-回收包装污染隐患】。", "guidance": "来源：《食品包装安全主持讨论手册》"},
  {"id": "MR138", "category": "食品引导", "text": "具备食品行业监管协同讨论框架构建能力，能归纳【政企协同漏洞-跨部门信息壁垒-行业协会自律作用-消费者监督渠道】。", "guidance": "来源：《食品安全社会共治主持议题设计指南》"},
  {"id": "MR139", "category": "食品引导", "text": "掌握预制菜食品安全讨论引导方法，可归纳【原料新鲜度把控-加工工艺卫生-冷链运输保障-加热食用安全】。", "guidance": "来源：《预制菜安全监管主持引导策略》"},
  {"id": "MR140", "category": "食品引导", "text": "熟悉食品添加剂新品种管理讨论焦点归纳能力，能梳理【新品种审批流程-安全性评估标准-实际应用监测-消费者知情权保障】。", "guidance": "来源：《食品添加剂新品种管理主持讨论框架》"},
  {"id": "MR141", "category": "食品引导", "text": "具备食品安全科普讨论引导技巧，可归纳【误区具体表现-科普内容适配性-传播渠道有效性-专家解读通俗化】。", "guidance": "来源：《食品安全科普主持议题设计规范》"},
  {"id": "MR142", "category": "食品引导", "text": "掌握重大活动食品安全保障讨论框架，可从【食材定点采购-全程闭环监管-快速检测部署-应急处置预案】维度分享保障经验。", "guidance": "来源：《重大活动食品安全主持引导手册》"},
  {"id": "MR143", "category": "食品引导", "text": "熟悉食品生产企业自查讨论引导方法，能归纳【自查制度完善度-问题整改实效-第三方审计作用-监管部门复核机制】。", "guidance": "来源：《食品企业自查监管主持议题设计策略》"},
  {"id": "MR144", "category": "食品引导", "text": "具备食品相关产品安全讨论焦点提炼能力，可梳理【产品质量标准-生产工艺合规-有害物质释放-使用寿命与安全关联】。", "guidance": "来源：《食品相关产品安全主持讨论框架》"},
  {"id": "MR145", "category": "食品引导", "text": "掌握食品安全责任保险讨论引导方法，能归纳【保险产品适配性-企业投保意愿-理赔流程简化-风险分担机制】。", "guidance": "来源：《食品安全保险主持引导策略》"},
  {"id": "MR146", "category": "食品引导", "text": "熟悉农村食品安全讨论焦点归纳技巧，可梳理【小卖部食品过期-流动摊贩监管难-假冒伪劣食品流入-消费维权意识薄弱】。", "guidance": "来源：《农村食品安全监管主持议题设计指南》"},
  {"id": "MR147", "category": "食品引导", "text": "具备食品行业数字化监管讨论框架构建能力，能归纳【大数据风险预警-人工智能视频巡查-区块链溯源应用-监管数据共享壁垒】。", "guidance": "来源：《食品数字化监管主持讨论手册》"},
  {"id": "MR148", "category": "食品引导", "text": "掌握保健食品监管讨论引导方法，可归纳【审批备案规范-标签说明书监管-销售渠道整治-消费者认知提升】。", "guidance": "来源：《保健食品监管主持引导策略》"},
  {"id": "MR149", "category": "食品引导", "text": "熟悉食品供应链韧性讨论焦点归纳能力，能梳理【供应链中断风险-应急储备机制-替代货源保障-跨区域调配效率】。", "guidance": "来源：《食品供应链安全主持议题设计规范》"},
  {"id": "MR150", "category": "食品引导", "text": "具备食品安全标准与国际接轨讨论引导技巧，可归纳【国际标准借鉴-本土化适配调整-标准更新协同-进出口贸易影响】。", "guidance": "来源：《食品安全标准国际化主持讨论框架》"},

  # ========== 四、引导市场监管专家聚焦核心议题的知识 (MR151-MR180) ==========
  {"id": "MR151", "category": "市场监管引导", "text": "掌握反垄断监管核心议题归纳方法，能梳理【垄断行为识别-调查取证难点-处罚标准适用-长效监管机制】。", "guidance": "来源：《反垄断监管主持议题设计指南》"},
  {"id": "MR152", "category": "市场监管引导", "text": "熟悉反不正当竞争讨论引导技巧，可归纳【混淆行为界定-商业贿赂隐蔽形式-虚假宣传认定-侵犯商业秘密取证】。", "guidance": "来源：《反不正当竞争主持引导策略》"},
  {"id": "MR153", "category": "市场监管引导", "text": "具备价格监管焦点提炼能力，能梳理【违法行为表现形式-取证技术手段-处罚力度适配-突发场景应对】。", "guidance": "来源：《市场价格监管主持讨论框架》"},
  {"id": "MR154", "category": "市场监管引导", "text": "掌握网络交易监管讨论框架构建能力，可从【平台责任界定-直播带货监管-个人信息保护-跨区域执法协同】维度分析。", "guidance": "来源：《网络交易监管主持议题设计规范》"},
  {"id": "MR155", "category": "市场监管引导", "text": "熟悉广告市场监管引导方法，能归纳【广告内容审核漏洞-平台审核责任-执法监管时效-行业自律作用】。", "guidance": "来源：《广告监管主持引导手册》"},
  {"id": "MR156", "category": "市场监管引导", "text": "具备产品质量监管讨论焦点归纳技巧，可梳理【抽检覆盖面-不合格产品召回-生产企业溯源-区域质量差异】。", "guidance": "来源：《产品质量监管主持议题设计策略》"},
  {"id": "MR157", "category": "市场监管引导", "text": "掌握特种设备安全监管引导逻辑，能归纳【定期检验执行-隐患排查效率-操作人员资质-应急处置能力】。", "guidance": "来源：《特种设备安全主持讨论框架》"},
  {"id": "MR158", "category": "市场监管引导", "text": "熟悉市场主体登记监管讨论引导方法，可归纳【虚假注册识别-变更登记规范-注销流程简化-僵尸企业清理】。", "guidance": "来源：《市场主体登记监管主持引导策略》"},
  {"id": "MR159", "category": "市场监管引导", "text": "具备计量监管讨论框架构建能力，能梳理【计量器具检定-贸易结算公平性-计量作弊识别-民生领域计量保障】。", "guidance": "来源：《计量监管主持议题设计指南》"},
  {"id": "MR160", "category": "市场监管引导", "text": "掌握认证认可监管讨论引导技巧，可归纳【认证流程合规性-机构资质管理-认证结果公信力-跨境认证互认】。", "guidance": "来源：《认证认可监管主持讨论手册》"},
  {"id": "MR161", "category": "市场监管引导", "text": "熟悉消费维权讨论引导方法，能归纳【高频投诉领域-举证责任分配-调解机制效率-群体性维权应对】。", "guidance": "来源：《消费维权主持引导策略》"},
  {"id": "MR162", "category": "市场监管引导", "text": "具备知识产权保护讨论焦点提炼能力，可梳理【侵权行为新形式-取证技术创新-跨区域执法协同-侵权赔偿标准】。", "guidance": "来源：《知识产权保护主持议题设计规范》"},
  {"id": "MR163", "category": "市场监管引导", "text": "掌握市场监管综合执法讨论框架，能从【执法队伍建设-跨部门协同机制-执法装备升级-执法人员权益保障】维度分析。", "guidance": "来源：《市场监管综合执法主持讨论框架》"},
  {"id": "MR164", "category": "市场监管引导", "text": "熟悉重点领域市场监管引导方法，可归纳【行业监管特性-突出违法问题-监管技术适配-与行业主管协同】。", "guidance": "来源：《重点领域市场监管主持引导手册》"},
  {"id": "MR165", "category": "市场监管引导", "text": "具备智慧监管讨论焦点归纳技巧，能梳理【大数据应用场景-人工智能监测精度-数据安全保障-基层监管适配性】。", "guidance": "来源：《市场监管智慧化转型主持议题设计策略》"},
  {"id": "MR166", "category": "市场监管引导", "text": "掌握外商投资市场监管引导方法，可归纳【监管标准统一性-外资企业合规监管-跨境执法协作-投资权益保障】。", "guidance": "来源：《外商投资监管主持引导策略》"},
  {"id": "MR167", "category": "市场监管引导", "text": "熟悉市场信用监管讨论框架构建能力，能梳理【信用信息归集-信用评价体系-失信联合惩戒-信用修复机制】。", "guidance": "来源：《市场信用监管主持议题设计指南》"},
  {"id": "MR168", "category": "市场监管引导", "text": "具备传销与直销监管讨论引导技巧，可归纳【行为识别难点-证据固定方法-跨区域打击协同-公众防范教育】。", "guidance": "来源：《传销与直销监管主持讨论手册》"},
  {"id": "MR169", "category": "市场监管引导", "text": "掌握应急管理市场监管引导方法，能归纳【价格稳定措施-物资供应保障-质量安全监管-舆情引导协同】。", "guidance": "来源：《应急状态市场监管主持引导策略》"},
  {"id": "MR170", "category": "市场监管引导", "text": "熟悉农贸市场监管讨论焦点提炼能力，可梳理【准入制度完善-溯源体系建设-环境卫生整治-活禽交易监管】。", "guidance": "来源：《农贸市场监管主持议题设计规范》"},
  {"id": "MR171", "category": "市场监管引导", "text": "具备跨区域市场监管讨论框架构建能力，能归纳【执法标准统一-信息共享壁垒-案件移送流程-协同监管机制】。", "guidance": "来源：《跨区域市场监管主持讨论框架》"},
  {"id": "MR172", "category": "市场监管引导", "text": "掌握未成年人市场保护讨论引导方法，可归纳【违规商品整治-广告内容规范-消费权益保障-家校社协同监管】。", "guidance": "来源：《未成年人市场保护主持引导手册》"},
  {"id": "MR173", "category": "市场监管引导", "text": "熟悉市场监管政策评估讨论引导技巧，可归纳【政策落地实效-企业合规成本-公众满意度-调整优化建议】。", "guidance": "来源：《市场监管政策评估主持议题设计策略》"},
  {"id": "MR174", "category": "市场监管引导", "text": "具备虚假违法广告协同监管讨论焦点归纳能力，能梳理【部门职责分工-平台审核责任-监测技术应用-处罚结果公示】。", "guidance": "来源：《虚假违法广告治理主持讨论框架》"},
  {"id": "MR175", "category": "市场监管引导", "text": "掌握网络平台责任监管引导方法，可归纳【主体审核义务-交易安全保障-知识产权保护-消费者权益维护】。", "guidance": "来源：《网络平台责任监管主持引导策略》"},
  {"id": "MR176", "category": "市场监管引导", "text": "熟悉农资市场监管讨论引导方法，能归纳【源头治理措施-质量抽检频次-农民维权渠道-农技服务协同】。", "guidance": "来源：《农资市场监管主持议题设计指南》"},
  {"id": "MR177", "category": "市场监管引导", "text": "具备市场监管信息化建设讨论框架构建能力，可从【系统整合程度-数据共享效率-基层操作便捷性-网络安全防护】维度分析。", "guidance": "来源：《市场监管信息化建设主持讨论手册》"},
  {"id": "MR178", "category": "市场监管引导", "text": "掌握旅游市场监管讨论引导技巧，能归纳【违法行为识别-异地执法协同-投诉快速响应-行业信用管理】。", "guidance": "来源：《旅游市场监管主持引导策略》"},
  {"id": "MR179", "category": "市场监管引导", "text": "熟悉小微企业监管讨论焦点提炼能力，可梳理【监管弹性把握-合规指导服务-减负政策落实-公平竞争保障】。", "guidance": "来源：《小微企业监管主持议题设计规范》"},
  {"id": "MR180", "category": "市场监管引导", "text": "具备市场监管国际合作讨论引导方法，能归纳【监管标准对接-案件协查机制-知识产权跨境保护-消费者权益国际协同】。", "guidance": "来源：《市场监管国际合作主持讨论框架》"},

  # ========== 五、跨领域协同引导与全局掌控核心知识 (MR181-MR220) ==========
  {"id": "MR181", "category": "跨领域协同", "text": "掌握跨领域议题共性提炼方法，针对交叉议题能归纳【政策协同盲区-监管责任重叠-数据共享障碍-公众关切焦点】，引导三类专家协同破题。", "guidance": "来源：《跨领域议题协同引导指南》"},
  {"id": "MR182", "category": "跨领域协同", "text": "熟悉多专家对话节奏把控技巧，可通过【领域轮循发言-焦点交叉提问-共识即时总结】机制，确保全局视角完整呈现。", "guidance": "来源：《多专家对话主持节奏管理策略》"},
  {"id": "MR183", "category": "跨领域协同", "text": "具备跨领域政策关联性挖掘能力，能从【教育减负-校外培训监管-市场价格规范】链条中提炼政策联动需求。", "guidance": "来源：《跨领域政策协同主持议题设计指南》"},
  {"id": "MR184", "category": "跨领域协同", "text": "掌握全局议题优先级动态调整方法，依据【突发案例影响-政策更新时效-专家共识程度】实时优化讨论顺序。", "guidance": "来源：《全局议题议程动态管理主持策略》"},
  {"id": "MR185", "category": "跨领域协同", "text": "熟悉多领域数据关联分析引导技巧，可将教育机构投诉数据、食品抽检数据、市场处罚数据交叉比对，挖掘系统性问题。", "guidance": "来源：《跨领域数据协同分析主持讨论框架》"},
  {"id": "MR186", "category": "跨领域协同", "text": "具备跨领域观点冲突调和能力，当专家存在分歧时可归纳【目标共性-分歧本质-折中路径】，引导理性协商。", "guidance": "来源：《跨领域观点冲突调和主持指南》"},
  {"id": "MR187", "category": "跨领域协同", "text": "掌握重大公共事件跨领域响应引导框架，能梳理【教育机构处置-食品风险溯源-市场监管执法-公众舆情回应】协同节点。", "guidance": "来源：《重大事件跨领域协同主持应对规范》"},
  {"id": "MR188", "category": "跨领域协同", "text": "熟悉跨领域监管空白识别技巧，通过【政策比对-案例分析-专家访谈】归纳监管盲区，引导专家共建解决方案。", "guidance": "来源：《跨领域监管空白识别主持议题设计策略》"},
  {"id": "MR189", "category": "跨领域协同", "text": "具备全局共识提炼与呈现能力，在多专家讨论后能将分散观点整合为【核心共识-差异化建议-待解问题】。", "guidance": "来源：《跨领域共识提炼主持实践手册》"},
  {"id": "MR190", "category": "跨领域协同", "text": "掌握跨领域科普协同引导方法，可引导不同领域专家从各自角度讲解同一议题，形成科普合力。", "guidance": "来源：《跨领域科普主持协同策略》"},
  {"id": "MR191", "category": "跨领域协同", "text": "熟悉多平台跨领域内容整合逻辑，针对不同传播形式调整【专业深度-通俗表达-领域配比】。", "guidance": "来源：《多平台跨领域内容主持适配指南》"},
  {"id": "MR192", "category": "跨领域协同", "text": "具备跨领域应急补位能力，当某领域专家临时缺席时，能通过【核心观点前置归纳-关联领域专家延伸解读】保障讨论完整性。", "guidance": "来源：《跨领域专家缺席主持补位策略》"},
  {"id": "MR193", "category": "跨领域协同", "text": "掌握跨领域政策效果联合评估引导框架，可从多维度设计评估指标，引导专家联合开展成效分析。", "guidance": "来源：《跨领域政策评估主持讨论框架》"},
  {"id": "MR194", "category": "跨领域协同", "text": "熟悉公众关切跨领域回应技巧，将公众疑问分类引导对应领域专家精准解答，形成全面回应体系。", "guidance": "来源：《公众关切跨领域回应主持指南》"},
  {"id": "MR195", "category": "跨领域协同", "text": "具备跨领域案例深度剖析能力，能引导多领域专家从不同维度实现立体解读。", "guidance": "来源：《跨领域案例剖析主持议题设计策略》"},
  {"id": "MR196", "category": "跨领域协同", "text": "掌握跨领域术语统一转化方法，将各领域专业术语转化为通用讨论语境，降低跨领域沟通成本。", "guidance": "来源：《跨领域术语统一主持转化手册》"},
  {"id": "MR197", "category": "跨领域协同", "text": "熟悉跨领域长效机制构建引导方法，可归纳【政策协同-数据共享-执法联动-公众参与】核心要素。", "guidance": "来源：《跨领域长效机制主持引导策略》"},
  {"id": "MR198", "category": "跨领域协同", "text": "具备全局讨论偏离矫正能力，当讨论陷入单一领域细节时可通过【回归核心议题-关联其他领域】拉回焦点。", "guidance": "来源：《全局讨论偏离矫正主持技巧》"},
  {"id": "MR199", "category": "跨领域协同", "text": "掌握跨领域创新经验提炼引导框架，从各领域中挖掘可复用创新点，引导专家讨论跨领域经验借鉴。", "guidance": "来源：《跨领域创新经验提炼主持讨论框架》"},
  {"id": "MR200", "category": "跨领域协同", "text": "熟悉跨领域风险协同防控引导方法，引导多领域专家从各自角度分析风险，构建防控体系。", "guidance": "来源：《跨领域风险防控主持议题设计指南》"},
  {"id": "MR201", "category": "跨领域协同", "text": "具备跨领域资源整合路径引导能力，能归纳各领域资源的互补性，引导专家讨论资源协同利用方案。", "guidance": "来源：《跨领域资源整合主持引导策略》"},
  {"id": "MR202", "category": "跨领域协同", "text": "掌握跨领域舆情协同应对引导框架，可梳理【官方回应分工-专家发声节奏-公众情绪疏导-后续整改公示】。", "guidance": "来源：《跨领域舆情应对主持讨论手册》"},
  {"id": "MR203", "category": "跨领域协同", "text": "熟悉跨领域标准协同构建引导技巧，引导不同领域专家从各自角度提出标准要求，形成统一标准体系。", "guidance": "来源：《跨领域标准协同主持议题设计规范》"},
  {"id": "MR204", "category": "跨领域协同", "text": "具备全局视角下信息留白设计能力，在归纳跨领域信息时保留【协同机制漏洞-技术应用瓶颈-政策衔接空白】。", "guidance": "来源：《全局视角信息留白主持设计策略》"},
  {"id": "MR205", "category": "跨领域协同", "text": "掌握跨领域行动方案落地引导方法，将专家共识拆解为各领域具体任务，引导专家明确落地责任。", "guidance": "来源：《跨领域行动方案落地主持引导指南》"},
  {"id": "MR206", "category": "跨领域协同", "text": "熟悉跨领域研究成果转化引导技巧，将各领域科研成果分类，引导专家讨论成果向政策、技术、服务转化的路径。", "guidance": "来源：《跨领域科研转化主持议题设计策略》"},
  {"id": "MR207", "category": "跨领域协同", "text": "具备全球视野下跨领域治理引导能力，借鉴国际经验引导专家讨论本土化适配与创新。", "guidance": "来源：《国际经验本土化主持引导手册》"},
  {"id": "MR208", "category": "跨领域协同", "text": "掌握跨领域青少年保护协同引导框架，引导多领域专家从各自角度形成保护合力。", "guidance": "来源：《青少年保护跨领域协同主持讨论框架》"},
  {"id": "MR209", "category": "跨领域协同", "text": "熟悉跨领域数字化协同引导方法，可归纳各领域数据共享需求与安全边界，引导专家讨论数据协同应用。", "guidance": "来源：《跨领域数字化协同主持引导策略》"},
  {"id": "MR210", "category": "跨领域协同", "text": "具备跨领域问题根源系统性分析引导能力，引导多领域专家深挖系统根源，提出根治方案。", "guidance": "来源：《跨领域系统分析主持议题设计指南》"},
  {"id": "MR211", "category": "跨领域协同", "text": "掌握跨领域政策解读协同技巧，邀请多领域专家共同解读政策，分别从各自维度拆解实现全面解读。", "guidance": "来源：《跨领域政策解读主持协同策略》"},
  {"id": "MR212", "category": "跨领域协同", "text": "熟悉跨领域公众参与引导方法，设计多元参与渠道，引导专家讨论公众参与跨领域治理的保障机制。", "guidance": "来源：《公众参与跨领域治理主持引导手册》"},
  {"id": "MR213", "category": "跨领域协同", "text": "具备跨领域应急演练协同引导能力，引导多领域专家协同设计演练流程，提升演练实效。", "guidance": "来源：《跨领域应急演练主持议题设计规范》"},
  {"id": "MR214", "category": "跨领域协同", "text": "掌握跨领域典型经验推广引导框架，从案例中提炼核心要素，引导专家讨论推广路径。", "guidance": "来源：《跨领域经验推广主持讨论框架》"},
  {"id": "MR215", "category": "跨领域协同", "text": "熟悉跨领域争议问题协同研判技巧，引导多领域专家形成综合研判。", "guidance": "来源：《跨领域争议研判主持引导策略》"},
  {"id": "MR216", "category": "跨领域协同", "text": "具备跨领域能力建设协同引导能力，能归纳各领域能力提升需求，引导专家讨论协同培训方案。", "guidance": "来源：《跨领域能力建设主持议题设计指南》"},
  {"id": "MR217", "category": "跨领域协同", "text": "掌握跨领域媒体沟通协同技巧，指导多领域专家形成【统一立场-各有侧重-相互呼应】的媒体发声体系。", "guidance": "来源：《跨领域媒体沟通主持协同手册》"},
  {"id": "MR218", "category": "跨领域协同", "text": "熟悉跨领域考核评价协同引导方法，设计联动考核指标，引导专家讨论考核体系优化。", "guidance": "来源：《跨领域考核评价主持引导策略》"},
  {"id": "MR219", "category": "跨领域协同", "text": "具备跨领域未来趋势联合研判引导能力，结合技术发展与政策导向，引导专家共同研判未来趋势。", "guidance": "来源：《跨领域趋势研判主持讨论框架》"},
  {"id": "MR220", "category": "跨领域协同", "text": "掌握跨领域成果可视化呈现方法，将多专家讨论成果转化为【协同机制图-责任分工表-实施路线图】。", "guidance": "来源：《跨领域成果可视化主持呈现指南》"},

  # ========== 六、批判性思维与深度引导核心知识 (MR221-MR250) ==========
  {"id": "MR221", "category": "批判思维", "text": "掌握专家观点批判性审视方法，通过【依据核查-逻辑检验-案例佐证-局限性分析】四步法引导专家反思观点的严谨性。", "guidance": "来源：《主持批判性思维应用指南》"},
  {"id": "MR222", "category": "批判思维", "text": "熟悉政策文件批判性解读技巧，可从【目标合理性-执行可行性-潜在风险-公众接受度】维度提出质疑。", "guidance": "来源：《公共政策批判性解读主持策略》"},
  {"id": "MR223", "category": "批判思维", "text": "具备案例典型性批判性评估能力，能识别【极端案例-过时案例-样本偏差案例】，引导专家选用更具代表性的案例。", "guidance": "来源：《案例批判性评估主持讨论框架》"},
  {"id": "MR224", "category": "批判思维", "text": "掌握数据真实性与局限性批判引导方法，可追问【抽检样本分布-检测标准-时间范围】，引导专家客观解读数据价值。", "guidance": "来源：《数据批判性解读主持引导手册》"},
  {"id": "MR225", "category": "批判思维", "text": "熟悉专家立场隐性影响识别技巧，通过【关联利益排查-过往观点比对-表述倾向性分析】引导专家明确立场边界。", "guidance": "来源：《专家立场批判性识别主持策略》"},
  {"id": "MR226", "category": "批判思维", "text": "具备传统监管模式批判性反思引导能力，可归纳【人工监管效率低-技术应用滞后-协同机制僵化】等弊端。", "guidance": "来源：《传统监管模式反思主持议题设计指南》"},
  {"id": "MR227", "category": "批判思维", "text": "掌握行业惯例批判性审视方法，引导专家剖析惯例合理性与合规风险，推动行业规范升级。", "guidance": "来源：《行业惯例批判性审视主持引导策略》"},
  {"id": "MR228", "category": "批判思维", "text": "熟悉技术应用批判性评估引导技巧，可归纳【技术优势-应用局限-伦理风险-替代方案】，引导专家理性评估技术价值。", "guidance": "来源：《技术应用批判性评估主持讨论框架》"},
  {"id": "MR229", "category": "批判思维", "text": "具备公众认知误区批判性澄清能力，引导专家从专业角度拆解误区，传递科学认知。", "guidance": "来源：《公众认知误区批判性澄清主持指南》"},
  {"id": "MR230", "category": "批判思维", "text": "掌握政策执行偏差批判性分析引导方法，可归纳【区域差异-执行阻力-监督缺失-配套不足】，引导专家讨论纠偏路径。", "guidance": "来源：《政策执行偏差批判性分析主持策略》"},
  {"id": "MR231", "category": "批判思维", "text": "熟悉跨领域解决方案局限性批判引导技巧，引导多领域专家全面评估方案。", "guidance": "来源：《跨领域方案批判性评估主持议题设计规范》"},
  {"id": "MR232", "category": "批判思维", "text": "具备学术观点批判性引用引导能力，要求专家标注观点【适用场景-研究方法-同行争议】。", "guidance": "来源：《学术观点批判性引用主持引导手册》"},
  {"id": "MR233", "category": "批判思维", "text": "掌握突发事件应对方案批判性复盘方法，引导专家反思【响应时效-处置精准度-善后效果-改进空间】。", "guidance": "来源：《应急方案批判性复盘主持策略》"},
  {"id": "MR234", "category": "批判思维", "text": "熟悉行业自律与政府监管关系批判性讨论引导方法，可提出【自律有效性边界-监管介入时机-二者协同缺陷】等问题。", "guidance": "来源：《自律与监管关系批判性讨论框架》"},
  {"id": "MR235", "category": "批判思维", "text": "具备国际经验本土化批判性借鉴引导能力，引导专家分析【文化适配性-成本可控性-制度兼容性】。", "guidance": "来源：《国际经验本土化批判主持引导指南》"},
  {"id": "MR236", "category": "批判思维", "text": "掌握消费者与经营者权益平衡批判性讨论引导技巧，引导专家讨论【消费者举证责任-经营者合规成本-监管公平性】。", "guidance": "来源：《权益平衡批判性讨论主持策略》"},
  {"id": "MR237", "category": "批判思维", "text": "熟悉监管技术伦理批判性审视引导能力，可归纳【隐私侵犯风险-算法偏见-数据滥用隐患-监管边界】。", "guidance": "来源：《监管技术伦理批判性审视主持议题设计规范》"},
  {"id": "MR238", "category": "批判思维", "text": "具备政策目标与实际效果偏差批判性分析引导方法，对比【目标覆盖率-实际达成率-质量】引导专家剖析偏差原因。", "guidance": "来源：《政策效果偏差批判性分析主持手册》"},
  {"id": "MR239", "category": "批判思维", "text": "掌握行业创新与风险防控平衡批判性讨论引导技巧，引导专家讨论【创新自由度-风险容忍度-监管适配性】。", "guidance": "来源：《创新与风险平衡批判性讨论框架》"},
  {"id": "MR240", "category": "批判思维", "text": "熟悉公众舆论与专业判断关系批判性引导方法，引导专家辩证看待【舆论影响政策偏向-专业判断忽视风险-二者良性互动机制】。", "guidance": "来源：《舆论与专业判断关系批判性引导策略》"},
  {"id": "MR241", "category": "批判思维", "text": "具备监管资源配置合理性批判性评估引导能力，引导专家分析【重点领域投入-投入产出比-资源浪费点-优化方向】。", "guidance": "来源：《监管资源配置批判性评估主持议题设计指南》"},
  {"id": "MR242", "category": "批判思维", "text": "掌握教育与市场边界批判性讨论引导技巧，引导多领域专家辩证分析边界。", "guidance": "来源：《教育与市场边界批判性讨论主持框架》"},
  {"id": "MR243", "category": "批判思维", "text": "熟悉标准制定科学性批判性审视引导方法，可追问【制定依据-人群覆盖-动态调整-国际接轨缺陷】。", "guidance": "来源：《标准制定批判性审视主持引导策略》"},
  {"id": "MR244", "category": "批判思维", "text": "具备执法裁量权合理性批判性讨论引导能力，引导专家分析【裁量标准-区域差异-情节认定-公平性】。", "guidance": "来源：《执法裁量权批判性讨论主持议题设计规范》"},
  {"id": "MR245", "category": "批判思维", "text": "掌握家校社协同育人批判性反思引导方法，引导多方反思协同机制。", "guidance": "来源：《协同育人批判性反思主持引导手册》"},
  {"id": "MR246", "category": "批判思维", "text": "熟悉食品安全【零风险】认知批判性澄清引导技巧，引导专家剖析【零风险误区-可接受风险标准-风险防控成本-公众沟通策略】。", "guidance": "来源：《食品安全风险认知批判性澄清主持策略》"},
  {"id": "MR247", "category": "批判思维", "text": "具备政策修订批判性建议引导能力，引导专家从【执法实操性-权益保障全面性-技术适配性-国际兼容性】提出修订建议。", "guidance": "来源：《政策修订批判性建议主持议题设计指南》"},
  {"id": "MR248", "category": "批判思维", "text": "掌握监管信息化建设批判性评估引导方法，引导专家分析【系统实用性-数据准确性-基层适配性-维护成本】。", "guidance": "来源：《监管信息化批判性评估主持讨论框架》"},
  {"id": "MR249", "category": "批判思维", "text": "熟悉教育评价体系批判性反思引导技巧，引导专家剖析【对学生全面发展的制约-对教师教学的误导-对教育生态的破坏】。", "guidance": "来源：《教育评价体系批判性反思主持引导策略》"},
  {"id": "MR250", "category": "批判思维", "text": "具备跨领域治理系统性缺陷批判性挖掘引导能力，通过【政策、技术、人员、机制】多维度排查引导专家挖掘系统性漏洞。", "guidance": "来源：《跨领域治理缺陷批判性挖掘主持议题设计规范》"},
]


def retrieve_moderator_rules(query: str, top_k: int = 3) -> List[Dict[str, str]]:
  """按关键词匹配返回最多 top_k 条主持人规则。

  匹配逻辑：
  - query 与规则文本/建议都转为小写
  - 用子串匹配统计命中 token 数
  - 得分为 0 的规则会被忽略；若全部为 0，则按原顺序取前 top_k 条
  """
  query = (query or "").strip()
  if not query:
    return MODERATOR_RULES[:top_k]

  q_tokens = [t for t in query.lower().replace("\n", " ").split(" ") if t]
  if not q_tokens:
    return MODERATOR_RULES[:top_k]

  scored = []
  for rule in MODERATOR_RULES:
    blob = f"{rule['text']} {rule['guidance']} {rule['category']}".lower()
    score = sum(1 for t in q_tokens if t in blob)
    if score > 0:
      scored.append((score, rule))

  if not scored:
    return MODERATOR_RULES[:top_k]

  scored.sort(key=lambda x: x[0], reverse=True)
  return [r for _, r in scored[:top_k]]


def format_moderator_rules_for_prompt(rules: List[Dict[str, str]]) -> str:
  """将若干条主持人规则格式化为多行文本，便于塞进 LLM prompt。"""
  lines: List[str] = []
  for r in rules:
    line = f"[{r['id']}]({r['category']}): {r['text']} 建议：{r['guidance']}"
    lines.append(line)
  return "\n".join(lines) if lines else "(当前规则库未返回匹配项)"
